18	const MemoDetail = () => {
19	  const md = useMediaQuery("md");
20	  const [shareImageDialogOpen, setShareImageDialogOpen] = useState(false);
21	  const params = useParams();
22	  const location = useLocation();
23	  const { state: locationState, hash } = location;
24	
25	  // Detect share mode from the route parameter.
26	  const shareToken = params.token;
27	  const isShareMode = !!shareToken;
28	
29	  // Primary memo fetch — share token or direct name.
30	  const memoNameFromParams = params.uid ? `${memoNamePrefix}${params.uid}` : "";
31	  const {
32	    data: memoFromDirect,
33	    error: directError,
34	    isLoading: directLoading,
35	  } = useMemo(memoNameFromParams, { enabled: !isShareMode && !!memoNameFromParams });
36	  const { data: memoFromShare, error: shareError, isLoading: shareLoading } = useSharedMemo(shareToken ?? "", { enabled: isShareMode });
37	
38	  const memo = isShareMode ? memoFromShare : memoFromDirect;
39	  const error = isShareMode ? shareError : directError;
40	  const isLoading = isShareMode ? shareLoading : directLoading;
41	  const memoName = memo?.name ?? memoNameFromParams;
42	
43	  useMemoDetailError({
44	    error: error as Error | null,
45	  });
46	
47	  const { data: parentMemo } = useMemo(memo?.parent || "", {
48	    enabled: !!memo?.parent,
49	  });
50	
51	  const {
52	    data: comments = [],
53	    fetchNextPage: fetchNextComments,
54	    hasNextPage: hasNextComments,
55	    isFetchingNextPage: isFetchingNextComments,
56	  } = useInfiniteMemoComments(memoName, {
57	    enabled: !!memo,
58	  });
59	
60	  // Scroll to the hash target once it's in the DOM. The effect re-runs as the memo loads (footnote
61	  // anchors) and as comments arrive (comment anchors), since the target may render in either; the
62	  // ref guards against re-scrolling the same hash on every later comments page-load.
63	  const scrolledHashRef = useRef("");
64	  useEffect(() => {
65	    if (!hash || scrolledHashRef.current === hash) return;
66	    const el = document.getElementById(decodeURIComponent(hash.slice(1)));
67	    if (!el) return;
68	    scrolledHashRef.current = hash;
69	    el.scrollIntoView({ behavior: "smooth", block: "center" });
70	  }, [hash, memo, comments]);
71	
72	  if (isShareMode) {
73	    const isNotFound = error instanceof ConnectError && (error.code === Code.NotFound || error.code === Code.Unauthenticated);
74	    if (isNotFound || (!isLoading && !memo)) {
75	      return <Navigate to="/404" replace />;
76	    }
77	  }
78	
79	  if (isLoading || !memo) {
80	    return null;
81	  }
82	
83	  // In share mode, rewrite attachment URLs to include the share token for unauthenticated access.
84	  const displayMemo = isShareMode
85	    ? { ...memo, attachments: withShareAttachmentLinks(memo.attachments as Attachment[], shareToken!) }
86	    : memo;
87	  const mentionResolutionContents = [displayMemo.content, ...comments.map((comment) => comment.content)];
88	
89	  return (
90	    <section className="@container w-full max-w-5xl min-h-full flex flex-col justify-start items-center sm:pt-3 md:pt-6 pb-8">
91	      {!md && (
92	        <MobileHeader>
93	          <MemoDetailSidebarDrawer memo={displayMemo} onShareImageOpen={() => setShareImageDialogOpen(true)} />
94	        </MobileHeader>
95	      )}
96	      <MentionResolutionProvider contents={mentionResolutionContents}>
97	        <div className={cn("w-full flex flex-row justify-start items-start px-4 sm:px-6 gap-6")}>
98	          <div className={cn("w-full md:w-[calc(100%-16.5rem)]")}>
99	            {parentMemo && (
100	              <div className="w-auto inline-block mb-2">
101	                <Link
102	                  className="px-3 py-1 border border-border rounded-lg max-w-xs w-auto text-sm flex flex-row justify-start items-center flex-nowrap text-muted-foreground hover:shadow hover:opacity-80"
103	                  to={`/${parentMemo.name}`}
104	                  state={locationState}
105	                  viewTransition
106	                >
107	                  <ArrowUpLeftFromCircleIcon className="w-4 h-auto shrink-0 opacity-60 mr-2" />
108	                  <span className="truncate">{parentMemo.content}</span>
109	                </Link>
110	              </div>
111	            )}
112	            <MemoView
113	              key={`${displayMemo.name}-${displayMemo.updateTime}`}
114	              memo={displayMemo}
115	              compact={false}
116	              parentPage={locationState?.from}
117	              shareImageDialogOpen={shareImageDialogOpen}
118	              showCreator
119	              showVisibility
120	              showPinned
121	              onShareImageDialogOpenChange={setShareImageDialogOpen}
122	            />
123	            <MemoCommentSection
124	              memo={displayMemo}
125	              comments={comments}
126	              parentPage={locationState?.from}
127	              hasMoreComments={hasNextComments}
128	              isFetchingMoreComments={isFetchingNextComments}
129	              onLoadMoreComments={fetchNextComments}
130	            />
131	          </div>
132	          {md && (
133	            <div className="sticky top-0 left-0 shrink-0 -mt-6 w-60 h-full">
134	              <MemoDetailSidebar className="py-6" memo={displayMemo} onShareImageOpen={() => setShareImageDialogOpen(true)} />
135	            </div>
136	          )}
137	        </div>
138	      </MentionResolutionProvider>
139	    </section>
140	  );
141	};
