6	interface UseMemoDetailErrorOptions {
7	  error: Error | null;
8	}
9	
10	const useMemoDetailError = ({ error }: UseMemoDetailErrorOptions) => {
11	  const navigateTo = useNavigateTo();
12	
13	  useEffect(() => {
14	    if (!error) {
15	      return;
16	    }
17	
18	    if (error instanceof ConnectError) {
19	      if (error.code === Code.Unauthenticated || error.code === Code.PermissionDenied || error.code === Code.NotFound) {
20	        navigateTo("/404", { replace: true });
21	        return;
22	      }
23	
24	      toast.error(error.message);
25	      return;
26	    }
27	
28	    toast.error(error.message);
29	  }, [error, navigateTo]);
30	};
31	
32	export default useMemoDetailError;
