13	type ExpiryOption = "never" | "1d" | "7d" | "30d";
14	
15	function getExpireDate(option: ExpiryOption): Date | undefined {
16	  if (option === "never") return undefined;
17	  const d = new Date();
18	  if (option === "1d") d.setDate(d.getDate() + 1);
19	  else if (option === "7d") d.setDate(d.getDate() + 7);
20	  else if (option === "30d") d.setDate(d.getDate() + 30);
21	  return d;
22	}
23	
24	function formatExpiry(share: MemoShare, t: ReturnType<typeof useTranslate>): string {
25	  if (!share.expireTime) return t("memo.share.never-expires");
26	  const d = timestampDate(share.expireTime);
27	  return t("memo.share.expires-on", { date: d.toLocaleDateString() });
28	}
