53	    }
54	  };
55	
56	  return (
57	    <div className="flex flex-col gap-1 rounded-md border border-border p-3">
58	      <div className="flex items-center justify-between gap-2">
59	        <span className="truncate font-mono text-xs text-muted-foreground">{url}</span>
60	        <div className="flex shrink-0 items-center gap-1">
61	          <Button variant="ghost" size="icon" className="h-7 w-7" onClick={handleCopy} title={t("memo.share.copy")}>
62	            {copied ? <CheckIcon className="h-3.5 w-3.5 text-success" /> : <CopyIcon className="h-3.5 w-3.5" />}
