5	import useNavigateTo from "./hooks/useNavigateTo";
6	import { useUserLocale } from "./hooks/useUserLocale";
7	import { useUserTheme } from "./hooks/useUserTheme";
8	import { cleanupExpiredOAuthState } from "./utils/oauth";
9	
10	const App = () => {
11	  const navigateTo = useNavigateTo();
12	  const { profile: instanceProfile, profileLoaded, generalSetting: instanceGeneralSetting } = useInstance();
13	
14	  // Apply user preferences reactively
15	  useUserLocale();
16	  useUserTheme();
17	
18	  // Clean up expired OAuth states on app initialization
19	  useEffect(() => {
20	    cleanupExpiredOAuthState();
21	  }, []);
22	
23	  // Redirect to sign up page if the instance needs initial setup (no users yet).
24	  // needsSetup is used instead of a missing admin so an instance that has lost its
25	  // admins isn't mistaken for a fresh install (which would create a normal user).
26	  // Guard with profileLoaded so a fetch failure doesn't incorrectly trigger the redirect.
27	  useEffect(() => {
28	    if (profileLoaded && instanceProfile.needsSetup) {
29	      navigateTo("/auth/signup");
30	    }
31	  }, [profileLoaded, instanceProfile.needsSetup, navigateTo]);
32	
33	  useEffect(() => {
34	    if (instanceGeneralSetting.additionalStyle) {
35	      const styleEl = document.createElement("style");
36	      styleEl.innerHTML = instanceGeneralSetting.additionalStyle;
37	      styleEl.setAttribute("type", "text/css");
38	      document.body.insertAdjacentElement("beforeend", styleEl);
39	    }
40	  }, [instanceGeneralSetting.additionalStyle]);
41	
42	  useEffect(() => {
43	    if (instanceGeneralSetting.additionalScript) {
44	      const scriptEl = document.createElement("script");
45	      scriptEl.innerHTML = instanceGeneralSetting.additionalScript;
46	      document.head.appendChild(scriptEl);
47	    }
48	  }, [instanceGeneralSetting.additionalScript]);
49	
50	  // Dynamic update metadata with customized profile
51	  useEffect(() => {
52	    if (!instanceGeneralSetting.customProfile) {
53	      return;
54	    }
55	
56	    document.title = instanceGeneralSetting.customProfile.title;
57	    const link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
58	    link.href = instanceGeneralSetting.customProfile.logoUrl || "/logo.webp";
59	  }, [instanceGeneralSetting.customProfile]);
60	
61	  return (
62	    <>
63	      <MemoFilterProvider>
64	        <Outlet />
65	      </MemoFilterProvider>
66	      <ScrollRestoration />
67	    </>
68	  );
69	};
70	
71	export default App;
72
